            /* Invalid parameter values */
            return;
        }

        /* Update LRU settings */
        lru_tune(hot_percent, warm_percent, hot_age_factor, warm_age_factor);
    } else if (strcmp(tokens[0].value, "mode") == 0) {
        if (ntokens != 2) {
