            /* Invalid number of tokens for 'temp_ttl' command */
            return;
        }

        uint32_t ttl = atoi(tokens[1].value);
        if (ttl < 0) {
            /* Invalid TTL value */
            return;
        }

        /* Set temporary TTL */
        lru_set_temp_ttl(ttl);
