        if (ntokens != 7)
            return;

        int hot_percent = atoi(tokens[1].value);
        int warm_percent = atoi(tokens[2].value);
        double hot_age_factor = atof(tokens[3].value);
        double warm_age_factor = atof(tokens[4].value);
        int hot_max_size = atoi(tokens[5].value);
        int warm_max_size = atoi(tokens[6].value);

        if (hot_percent < 0 || hot_percent > 100 ||
            warm_percent < 0 || warm_percent > 100 ||
            hot_age_factor <= 0.0 || warm_age_factor <= 0.0 ||
            hot_max_size <= 0 || warm_max_size <= 0) {
            return;
        }

        c->hot_percent = hot_percent;
        c->warm_percent = warm_percent;
        c->hot_age_factor = hot_age_factor;
        c->warm_age_factor = warm_age_factor;
        c->hot_max_size = hot_max_size;
        c->warm_max_size = warm_max_size;

    } else if (strncmp(tokens[0].value, "mode", tokens[0].value) == 0) {
        if (ntokens != 2)
            return;

        if (strncmp(tokens[1].value, "single", tokens[1].length) == 0) {
            c->lru_mode = LRU_MODE_SINGLE;
        } else if (strncmp(tokens[1].value, "dual", tokens[1].length) == 0) {
            c->lru_mode = LRU_MODE_DUAL;
        } else {
            return;
        }

    } else if (strncmp(tokens[0].value, "temp_ttl", tokens[0].length) == 0) {
        if (ntokens != 2)
            return;

        int temp_ttl = atoi(tokens[1].value);
